func NewRoleValueNull() RoleValue {
	return RoleValue{
		state: attr.ValueStateNull,
	}
}

func NewRoleValueUnknown() RoleValue {
	return RoleValue{
		state: attr.ValueStateUnknown,
	}
}

func NewRoleValue(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) (RoleValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	// Reference: https://github.com/hashicorp/terraform-plugin-framework/issues/521
	ctx := context.Background()

	for name, attributeType := range attributeTypes {
		attribute, ok := attributes[name]

		if !ok {
			diags.AddError(
				"Missing RoleValue Attribute Value",
				"While creating a RoleValue value, a missing attribute value was detected. "+
					"A RoleValue must contain values for all attributes, even if null or unknown. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("RoleValue Attribute Name (%s) Expected Type: %s", name, attributeType.String()),
			)

			continue
		}

		if !attributeType.Equal(attribute.Type(ctx)) {
			diags.AddError(
				"Invalid RoleValue Attribute Type",
				"While creating a RoleValue value, an invalid attribute value was detected. "+
					"A RoleValue must use a matching attribute type for the value. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("RoleValue Attribute Name (%s) Expected Type: %s\n", name, attributeType.String())+
					fmt.Sprintf("RoleValue Attribute Name (%s) Given Type: %s", name, attribute.Type(ctx)),
			)
		}
	}

	for name := range attributes {
		_, ok := attributeTypes[name]

		if !ok {
			diags.AddError(
				"Extra RoleValue Attribute Value",
				"While creating a RoleValue value, an extra attribute value was detected. "+
					"A RoleValue must not contain values beyond the expected attribute types. "+
					"This is always an issue with the provider and should be reported to the provider developers.\n\n"+
					fmt.Sprintf("Extra RoleValue Attribute Name: %s", name),
			)
		}
	}

	if diags.HasError() {
		return NewRoleValueUnknown(), diags
	}

	builtinAttribute, ok := attributes["builtin"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`builtin is missing from object`)

		return NewRoleValueUnknown(), diags
	}

	builtinVal, ok := builtinAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`builtin expected to be basetypes.StringValue, was: %T`, builtinAttribute))
	}

	customAttribute, ok := attributes["custom"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`custom is missing from object`)

		return NewRoleValueUnknown(), diags
	}

	customVal, ok := customAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`custom expected to be basetypes.StringValue, was: %T`, customAttribute))
	}

	nameAttribute, ok := attributes["name"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`name is missing from object`)

		return NewRoleValueUnknown(), diags
	}

	nameVal, ok := nameAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`name expected to be basetypes.StringValue, was: %T`, nameAttribute))
	}

	rankAttribute, ok := attributes["rank"]

	if !ok {
		diags.AddError(
			"Attribute Missing",
			`rank is missing from object`)

		return NewRoleValueUnknown(), diags
	}

	rankVal, ok := rankAttribute.(basetypes.StringValue)

	if !ok {
		diags.AddError(
			"Attribute Wrong Type",
			fmt.Sprintf(`rank expected to be basetypes.StringValue, was: %T`, rankAttribute))
	}

	if diags.HasError() {
		return NewRoleValueUnknown(), diags
	}

	return RoleValue{
		Builtin: builtinVal,
		Custom:  customVal,
		Name:    nameVal,
		Rank:    rankVal,
		state:   attr.ValueStateKnown,
	}, diags
}

func NewRoleValueMust(attributeTypes map[string]attr.Type, attributes map[string]attr.Value) RoleValue {
	object, diags := NewRoleValue(attributeTypes, attributes)

	if diags.HasError() {
		// This could potentially be added to the diag package.
		diagsStrings := make([]string, 0, len(diags))

		for _, diagnostic := range diags {
			diagsStrings = append(diagsStrings, fmt.Sprintf(
				"%s | %s | %s",
				diagnostic.Severity(),
				diagnostic.Summary(),
				diagnostic.Detail()))
		}

		panic("NewRoleValueMust received error(s): " + strings.Join(diagsStrings, "\n"))
	}

	return object
}

func (t RoleType) ValueFromTerraform(ctx context.Context, in tftypes.Value) (attr.Value, error) {
	if in.Type() == nil {
		return NewRoleValueNull(), nil
	}

	if !in.Type().Equal(t.TerraformType(ctx)) {
		return nil, fmt.Errorf("expected %s, got %s", t.TerraformType(ctx), in.Type())
	}

	if !in.IsKnown() {
		return NewRoleValueUnknown(), nil
	}

	if in.IsNull() {
		return NewRoleValueNull(), nil
	}

	attributes := map[string]attr.Value{}

	val := map[string]tftypes.Value{}

	err := in.As(&val)

	if err != nil {
		return nil, err
	}

	for k, v := range val {
		a, err := t.AttrTypes[k].ValueFromTerraform(ctx, v)

		if err != nil {
			return nil, err
		}

		attributes[k] = a
	}

	return NewRoleValueMust(RoleValue{}.AttributeTypes(ctx), attributes), nil
}

func (t RoleType) ValueType(ctx context.Context) attr.Value {
	return RoleValue{}
}

var _ basetypes.ObjectValuable = RoleValue{}

type RoleValue struct {
	Builtin basetypes.StringValue `tfsdk:"builtin"`
	Custom  basetypes.StringValue `tfsdk:"custom"`
	Name    basetypes.StringValue `tfsdk:"name"`
	Rank    basetypes.StringValue `tfsdk:"rank"`
	state   attr.ValueState
}

func (v RoleValue) ToTerraformValue(ctx context.Context) (tftypes.Value, error) {
	attrTypes := make(map[string]tftypes.Type, 4)

	var val tftypes.Value
	var err error

	attrTypes["builtin"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["custom"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["name"] = basetypes.StringType{}.TerraformType(ctx)
	attrTypes["rank"] = basetypes.StringType{}.TerraformType(ctx)

	objectType := tftypes.Object{AttributeTypes: attrTypes}

	switch v.state {
	case attr.ValueStateKnown:
		vals := make(map[string]tftypes.Value, 4)

		val, err = v.Builtin.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["builtin"] = val

		val, err = v.Custom.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["custom"] = val

		val, err = v.Name.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["name"] = val

		val, err = v.Rank.ToTerraformValue(ctx)

		if err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		vals["rank"] = val

		if err := tftypes.ValidateValue(objectType, vals); err != nil {
			return tftypes.NewValue(objectType, tftypes.UnknownValue), err
		}

		return tftypes.NewValue(objectType, vals), nil
	case attr.ValueStateNull:
		return tftypes.NewValue(objectType, nil), nil
	case attr.ValueStateUnknown:
		return tftypes.NewValue(objectType, tftypes.UnknownValue), nil
	default:
		panic(fmt.Sprintf("unhandled Object state in ToTerraformValue: %s", v.state))
	}
}

func (v RoleValue) IsNull() bool {
	return v.state == attr.ValueStateNull
}

func (v RoleValue) IsUnknown() bool {
	return v.state == attr.ValueStateUnknown
}

func (v RoleValue) String() string {
	return "RoleValue"
}

func (v RoleValue) ToObjectValue(ctx context.Context) (basetypes.ObjectValue, diag.Diagnostics) {
	var diags diag.Diagnostics

	attributeTypes := map[string]attr.Type{
		"builtin": basetypes.StringType{},
		"custom":  basetypes.StringType{},
		"name":    basetypes.StringType{},
		"rank":    basetypes.StringType{},
	}

	if v.IsNull() {
		return types.ObjectNull(attributeTypes), diags
	}

	if v.IsUnknown() {
		return types.ObjectUnknown(attributeTypes), diags
	}

	objVal, diags := types.ObjectValue(
		attributeTypes,
		map[string]attr.Value{
			"builtin": v.Builtin,
			"custom":  v.Custom,
			"name":    v.Name,
			"rank":    v.Rank,
		})

	return objVal, diags
}

func (v RoleValue) Equal(o attr.Value) bool {
	other, ok := o.(RoleValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.Builtin.Equal(other.Builtin) {
		return false
	}

	if !v.Custom.Equal(other.Custom) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.Rank.Equal(other.Rank) {
		return false
	}

	return true
}

func (v RoleValue) Type(ctx context.Context) attr.Type {
	return RoleType{
		basetypes.ObjectType{
			AttrTypes: v.AttributeTypes(ctx),
		},
	}
}

func (v RoleValue) AttributeTypes(ctx context.Context) map[string]attr.Type {
	return map[string]attr.Type{
		"builtin": basetypes.StringType{},
		"custom":  basetypes.StringType{},
		"name":    basetypes.StringType{},
		"rank":    basetypes.StringType{},
	}
}
